import { Table, TableProps, Tag, Tooltip, Typography, Image, Space, Popover, Message } from '@arco-design/web-react';
import React, { useMemo, useState } from 'react';
import './style.less';
import TableFixed from './TableFixed';
import classNames from 'classnames';
import TableFixedMove from './TableFixedMove';
import { ProColumn, ProTableProps } from './interface';
import Icon from '@/components/Icon';
import i18next from 'i18next';
import { IconCopy, IconInfoCircle } from '@arco-design/web-react/icon';
import { copyText } from '@/utils';

export default function ProTable({ tableMode = 'resizable' , ...props }: ProTableProps){

    const TableElement = useMemo(() => {
        if(tableMode == 'resizable') return TableFixed;
        else if(tableMode == 'move') return TableFixedMove;
        return Table;
    },[tableMode])

    const columns: TableProps['columns'] = useMemo(() => {
        return (props.columns || []).map((o) => {
            const { valueEnum, format, proCopyValue, fieldProps, copyable, tooltip, addBefore, addAfter, ...item } = o;
            if(addBefore || addAfter){
                return {
                    render: (col) => `${addBefore || ''}${col}${addAfter || ''}`,
                    ...item,
                }
            }
            if(format){
                switch(format){
                    case "copy":
                        item.render = (col, rowData) => {
                            return (
                                <div className="flex items-center cursor-pointer"
                                    onClick={() => {
                                        copyText(proCopyValue? proCopyValue(rowData) : col).then(() => {
                                            Message.success("复制成功");
                                        })
                                    }}
                                >
                                    <div className="mr-2">{col}</div>
                                    <IconCopy />
                                </div>
                            )
                        }
                    break;
                    case "i18n":
                        return {
                            render: (col, rowData) => i18next.t(col, rowData),
                            ...item,
                        }
                    case "tags":
                        return {
                            render: (col) => {
                                const { labelField="label" } = fieldProps || {}
                                if(Array.isArray(col)){
                                    return (
                                        <Space size="small" className="flex flex-wrap">
                                            {(col.slice(0,1)).map((o, i) => {
                                                return (
                                                    <Tag key={i} color='arcoblue'>{o[labelField]}</Tag>
                                                )
                                            })}
                                            {col.length > 1? (
                                                <Popover content={(
                                                    <Space size="small">
                                                        {col.map((o, i) => {
                                                            return (
                                                                <Tag key={i} color='arcoblue'>{o[labelField]}</Tag>
                                                            )
                                                        })}
                                                    </Space>
                                                )}>
                                                    <Tag key="sum" color='arcoblue'>
                                                        +{ col.length - 1 }
                                                    </Tag>
                                                </Popover>
                                            ): null}
                                        </Space>
                                    )
                                }
                                return null;
                            },
                            ...item
                        }
                    case "image":
                        return {
                            render: (col) => {
                                return (
                                    <Image src={col} height={30} />
                                )
                            },
                            ...item
                        }
                    break;
                    case "icon":
                        return {
                            render: (col) => {
                                return (
                                    <Icon value={col} />
                                )
                            },
                            ...item
                        }
                    break;
                }
            }
            if(valueEnum){
                return {
                    render: (col) => {
                        // undefined 为默认类型，当参数不匹配的时候会使用undefined作为默认参数
                        if(valueEnum[col]){
                            if('color' in valueEnum[col]){
                                return (
                                    <Tag color={valueEnum[col].color}>
                                        {valueEnum[col].label}
                                    </Tag>
                                )
                            }else {
                                return valueEnum[col].label
                            }
                        }
                        return col;
                    },
                    ...item
                }
            }else if(copyable){
                return {
                    render: (value) => {
                        if(value){
                            const element = (
                                <Typography.Paragraph
                                    ellipsis={item.ellipsis}
                                    className="pro-table-typography"
                                    copyable
                                >{value}</Typography.Paragraph>
                            )
                            if(item.ellipsis){
                                return (
                                    <Tooltip content={value}>
                                        {element}
                                    </Tooltip>
                                )
                            }
                            return element;
                        }
                        return value;
                    },
                    ...item
                }
            }
            if(typeof o.title === "string"){
                if(tooltip){
                    item.title = (
                        <div>
                            {item.title}
                            <Tooltip content={tooltip}>
                                <IconInfoCircle />
                            </Tooltip>
                        </div>
                    ) 
                }
            }
            return item;
        })
    },[props.columns])

    const className = useMemo(() => {
        if(!props.scroll) return props.className;
        return classNames(props.className, {
            'table-scroll-y-full': props.scroll.y === true,
        })
    },[props.scroll, props.className])


    return (
        <TableElement
            rowKey="id"
            {...props}
            className={className}
            columns={columns}
        />
    )
}

ProTable.TableFixed = TableFixed;
ProTable.TableFixedMove = TableFixedMove;